# -*- coding: utf-8 -*-
import json, re, glob
IQ = '/tmp/claude-0/-home-user-Pruebas/978f574d-1019-54bc-bb45-9f4fddd102bb/scratchpad/iq'
D = {}
for p in glob.glob(IQ + '/I*/passages.json'):
    d = json.load(open(p, encoding='utf8'))
    if isinstance(d, dict): d = d.get('items') or list(d.values())[0]
    for r in d: D[r['id']] = r
def _cut(t, a, b):
    if a: t = t[t.index(a):]
    if b: t = t[:t.index(b) + len(b)]
    return t
def clean(t): return re.sub(r'\s+', ' ', re.sub(r'\[(?:p\. ?\d+|Latin continues[^\]]*|\.\.\.)\]', '…', t)).strip()
def L(i, a=None, b=None): return clean(_cut(D[i]['greek'], a, b))
def EN(i, a=None, b=None): return clean(_cut(D[i]['english'], a, b))
def TX(i, a=None, b=None): return clean(_cut(D[i]['greek'], a, b))
H = 'Latín: Harvey 1857 (Cambridge), leído por un investigador en el escaneo'
HV = 'Latín: Harvey 1857 vol. 2, p. 213; la página la vi yo en imagen (captura IR20)'
ANF = 'Inglés: Roberts y Rambaut, ANF vol. 1'
ROB = 'Inglés: Robinson 1920 (SPCK); no se leyó el armenio'
def Q(i, lang, txt, es, ref, src): return dict(id=i, lang=lang, txt=txt, es=es, ref=ref, src=src)
S = []
def add(id, title, sub, quotes, res): S.append(dict(id=id, title=title, sub=sub, quotes=quotes, res=res))

add('IR01', 'Quién es Ireneo y qué conservamos de él', 'Latín (casi todo), unos pocos fragmentos griegos y una obra solo en armenio',
 [Q('I10-17','en',TX('I10-17'),'Los mismos testigos recomendaron también a Ireneo, que ya entonces era presbítero de la parroquia de Lyon, al obispo de Roma antes citado, diciendo muchas cosas favorables de él, como muestra el extracto siguiente: «Rogamos, padre Eleuterio, que te alegres en Dios en todo y siempre. Hemos pedido a nuestro hermano y compañero Ireneo que te lleve esta carta, y te rogamos que lo tengas en estima, como celoso del pacto de Cristo».','Eusebio, Hist. eccl. 5.4.1-2','Inglés: McGiffert, NPNF 2.ª serie vol. 1'),
  Q('I10-20','en',TX('I10-20', None, 'On apostolical preaching,') if False else TX('I10-20')[:520],'Ireneo, presbítero bajo el obispo Potino, que gobernaba la Iglesia de Lyon, enviado a Roma como legado por los mártires […]. Escribió cinco libros Contra las herejías y un breve volumen Contra los gentiles y otro Sobre la disciplina, una carta a su hermano Marciano Sobre la predicación apostólica, un libro de Tratados varios […]','Jerónimo, De viris ill. 35','Inglés: Richardson, NPNF 2.ª serie vol. 3')],
 '<b>Quién.</b> Ireneo (c. 130-c. 202), discípulo de Policarpo, presbítero y luego obispo de Lyon. <b>Qué conservamos.</b> <i>Contra las herejías</i> (5 libros) casi solo en una traducción <b>latina muy literal</b>; el griego sobrevive en fragmentos citados por Hipólito, Eusebio, Epifanio y otros; y la <i>Demostración de la predicación apostólica</i> solo en <b>armenio</b> (usé el inglés de Robinson 1920, no leí el armenio). <b>Cautelas.</b> (1) Hablamos del latín de un traductor: Bull (vol. 2, p. 391) advierte que el traductor vertía <i>énnoia, sigḗ</i> y <i>noûs</i> de un modo peculiar. (2) Los llamados «Fragmentos de Pfaff» son <b>dudosos o espurios</b>: no los uso. (3) Jerónimo (35) solo lista obras; Eusebio y Jerónimo no dan contenido trinitario. <b>Límite.</b> La numeración de Harvey y de la ANF difiere (p. ej. ANF 3.16.6 = Harvey 3.17.6): cito ANF y señalo Harvey.')

add('IR02', 'La regla de fe: Padre, Cristo Jesús Hijo de Dios, Espíritu Santo', 'Las fórmulas trinitarias más antiguas de Ireneo',
 [Q('I1-01','la',L('I1-01', None, 'qui per Prophetas praedicavit'),'Pues la Iglesia, diseminada por todo el orbe hasta los confines de la tierra, recibió de los apóstoles y de sus discípulos esta fe: en un solo Dios, Padre omnipotente, que hizo el cielo, la tierra, el mar y todo lo que hay en ellos; y en un solo Cristo Jesús, Hijo de Dios, encarnado por nuestra salvación; y en el Espíritu Santo, que por los profetas predicó […]','Contra las herejías 1.10.1 (Harvey, p. 90)',H),
  Q('I6-13','la',L('I6-13'),'[…] al Hijo de Dios, Cristo Jesús nuestro Señor, por quien todo, y sus disposiciones por las cuales el hombre se hizo hijo de Dios: firme creencia que está en el Espíritu de Dios, que presta el conocimiento de la verdad, que expuso las disposiciones del Padre y del Hijo, según las cuales estaba presente al género humano, como quiere el Padre.','Contra las herejías 4.33.7 (Harvey vol. 2, p. 262)',H),
  Q('I8-04','en',EN('I8-04'),'Dios Padre, no hecho, no material, invisible; un solo Dios, creador de todo: éste es el primer punto de nuestra fe. El segundo punto es: el Verbo de Dios, Hijo de Dios, Cristo Jesús nuestro Señor, que se manifestó a los profetas […]: por quien todo fue hecho; […] Y el tercer punto es: el Espíritu Santo, por quien los profetas profetizaron y los padres aprendieron las cosas de Dios […]','Demostración 6 (Robinson, pp. 74-75)',ROB)],
 '<b>Qué dice.</b> Tres «puntos» (no «artículos», como suele citarse: la expresión «tres artículos» no está en el texto): Padre, Verbo-Hijo-Cristo Jesús, Espíritu Santo; el bautismo se da en el nombre del Padre, del Hijo y del Espíritu (Dem. 3: «en el nombre de Dios Padre, y en el nombre de Jesucristo, Hijo de Dios… y en el Espíritu Santo de Dios»). <b>Límite.</b> Son fórmulas de confesión: no dicen «consustancial» ni definen la relación; en 4.33.7 el Espíritu «expone las disposiciones del Padre y del Hijo… como quiere el Padre». El Verbo es «Hijo de Dios» y «Verbo»; el Espíritu, quien inspira a los profetas.')

add('IR03', 'Dios hizo todo «por su Verbo y su Espíritu» (1.22.1) y «por el Verbo y la Sabiduría» (2.30.9)', 'Tres fórmulas distintas: cuidado con atribuir una a otra',
 [Q('I1-02','la',L('I1-02', 'Cum teneamus', 'Pater Domini nostri J'),'Y manteniendo nosotros la regla de la verdad, es decir, que hay un solo Dios omnipotente, que todo lo fundó por su Verbo, y lo ordenó, y lo hizo de lo que no era, para que todo exista […] no por ángeles, ni por ciertas potencias separadas de su pensamiento (pues Dios no necesita nada de todo eso), sino haciendo, disponiendo, gobernando y dando el ser a todo por su Verbo y su Espíritu: éste que hizo el mundo […] éste es el Padre de nuestro Señor Jesucristo […]','Contra las herejías 1.22.1 (Harvey, pp. 188-189)',H),
  Q('I1-07','la',L('I1-07'),'[…] sin necesitar nada, Dios por el Verbo fundó y lo hizo todo; ni necesitando ángeles como auxiliares para lo que se hace […] sino que él mismo en sí mismo […] hizo como quiso; dando a todo su armonía, su orden y el comienzo de la creación […] y todo lo que ha sido hecho lo hizo por el Verbo infatigable.','Contra las herejías 2.2.4 (Harvey, pp. 255-256)',H),
  Q('I2-14','la',L('I2-14'),'Pero un solo Dios artífice, el que está sobre todo principado, potestad, dominación y virtud: éste Padre, éste Dios, éste fundador, éste hacedor, éste artífice, que hizo por sí mismo, es decir, por su Verbo y por su Sabiduría, el cielo y la tierra, y los mares y todo lo que hay en ellos […]','Contra las herejías 2.30.9 (Harvey, p. 368)',H)],
 '<b>Corrección.</b> Se suele citar 2.2.4-5 o 2.30.9 como «Verbo y Espíritu»: <b>no lo son</b>. 2.2.4-5 dice solo <b>«Verbo»</b>; 2.30.9, <b>«Verbo y Sabiduría»</b>; la fórmula <b>«Verbo y Espíritu»</b> es 1.22.1; y la identificación «Sabiduría = Espíritu» llega en 4.20.3 (IR10). <b>Qué significa.</b> No son tres doctrinas rivales: en cada contexto Ireneo niega que Dios necesite <b>ángeles o potencias intermedias</b> (los eones gnósticos) y afirma que obra «por sí mismo», es decir, por su Verbo (y su Sabiduría/Espíritu), que no son seres ajenos. <b>Objeción.</b> «Por» (<i>per</i>) suena instrumental; <b>respuesta</b>: Ireneo dice que son «<i>sua</i>» («su Verbo… suya») y que Dios actúa «por sí mismo» al actuar por ellos (IR09). <b>Límite.</b> Latín: el griego de 1.22.1 no se conserva completo.')

add('IR04', 'Pasaje difícil A (2.13, 2.28.5): Dios «todo mente, todo Verbo», y el Verbo no es una «tercera emisión»', 'Contra los eones valentinianos; la frase «la Mente… es el Padre mismo»',
 [Q('I1-09','la',L('I1-09'),'Pues el Padre de todo dista mucho de las afecciones y pasiones que les pasan a los hombres: simple, no compuesto, sin miembros diversos, totalmente semejante e igual a sí mismo, siendo todo sentido, todo espíritu, todo sensibilidad, todo pensamiento, todo razón, todo oído, todo ojo, todo luz y toda fuente de todos los bienes, como corresponde decir de Dios a los religiosos y piadosos.','Contra las herejías 2.13.3 (Harvey, p. 282)',H),
  Q('I2-07','la',L('I2-07'),'Pero Dios, siendo todo Mente y todo Verbo (<i>Logos</i>), lo que piensa, eso mismo dice; lo que dice, eso mismo piensa. Pues su pensamiento es el Verbo, y el Verbo es la Mente, y la Mente que lo abarca todo es el Padre mismo.','Contra las herejías 2.28.5 (Harvey, pp. 354-355)',H+' (partly: OCR)'),
  Q('I2-08','la',L('I2-08'),'Quien, pues, dice «mente de Dios» y atribuye a la mente una emisión propia, lo declara compuesto, como si Dios fuera una cosa y la Mente principal otra. Igualmente también respecto del Verbo, dándole una tercera emisión desde el Padre; de donde ignora también su grandeza y separa lejos al Verbo de Dios.','Contra las herejías 2.28.5 (Harvey, p. 355)',H)],
 '<b>Por qué es difícil.</b> «La Mente que lo abarca todo es el Padre mismo» suena modalista (Verbo = Mente = Padre), y «prolatio» rechazada parece negar toda generación del Hijo. <b>Resolución.</b> (1) El contexto es <b>anti-valentiniano</b>: los gnósticos hacían salir del Padre, en una <b>serie temporal</b> (Mente, luego Verbo, luego Vida), una pareja tras otra; Ireneo responde que en Dios «no hay nada más antiguo ni más reciente» (2.13.8: «<i>nec aliud antiquius, nec posterius</i>»). (2) Rechaza la <b>emisión como separación</b> («separa lejos al Verbo de Dios»), no que el Verbo tenga origen en el Padre (lo afirma en 2.28.6: IR06). (3) La lectura nicena es la de la generación <b>eterna</b>, no temporal ni «emisión» (Agustín, <i>De Trin.</i> XV; Atanasio, Or. 1.20). <b>Límite.</b> Ni el latín ni el griego (que casi no se conserva) permiten afirmar una doctrina elaborada de personas: Ireneo defiende ante todo la simplicidad de Dios. Bull (vol. 2, p. 391) nota además el problema del traductor latino.')

add('IR05', 'Pasaje difícil B (2.28.6, 2.28.8): «ni el Hijo, sino sólo el Padre» y «el Padre es mayor que yo»', 'Marcos 13:32 en Ireneo',
 [Q('I2-09','la',L('I2-09'),'Pero hinchados sin razón, decís atrevidamente que conocéis los misterios inenarrables de Dios; cuando el mismo Señor, el propio Hijo de Dios, concedió que sólo el Padre conoce el día y la hora del juicio, diciendo claramente: «Pero de aquel día y de aquella hora nadie sabe, ni el Hijo, sino el Padre solo».','Contra las herejías 2.28.6 (Harvey, p. 355; en inglés, ANF p. 401, captura IR21)',H),
  Q('I2-10','la',L('I2-10'),'Si, pues, el Hijo no se avergonzó de remitir al Padre el conocimiento de aquel día, sino que dijo lo verdadero, tampoco nosotros nos avergoncemos de reservar a Dios lo que en las cuestiones es mayor que nosotros. Pues nadie está sobre el maestro.','Contra las herejías 2.28.6 (Harvey, p. 355)',H),
  Q('I2-13','la',L('I2-13'),'Pues si alguien busca la causa por la que, comunicando el Padre al Hijo todas las cosas, el Señor manifestó que sólo el Padre sabe la hora y el día, no encontrará otra más conveniente, ni más decente, ni sin peligro, que ésta: pues el Señor es el único maestro verdadero, para que aprendamos por medio de él que el Padre está sobre todo. Pues dice: «El Padre es mayor que yo».','Contra las herejías 2.28.8 (Harvey, p. 357)',H)],
 '<b>Por qué es difícil.</b> Es el texto central de arrianos y unitarios: el Hijo no sabe el día; «el Padre es mayor». <b>Resolución.</b> (1) Ireneo no concluye que el Hijo sea inferior en naturaleza, sino que enseña <b>humildad</b> («reservar a Dios lo que es mayor que nosotros»). (2) La misma frase dice «<i>Pater communicans Filio</i> en todo»: el Padre <b>comunica todo</b> al Hijo, salvo (según el texto) esa hora. (3) La tradición posterior da la clave: el Hijo «ignora» el día porque <b>no lo revela</b> (Agustín, <i>De Trin.</i> I.12; Aquino, ST III q.10 a.2 ad 1) o lo ignora «como hombre» (Atanasio, Or. 3.45). <b>Límite.</b> Ireneo <b>no da esa explicación</b>: ofrece solo una regla de prudencia; la ANF anota que cita Mc 13:32 «de memoria» (omite «ni los ángeles»). «Mayor» (<i>major</i>) en 2.28.8 es de Jn 14:28 y queda como subordinación de origen.')

add('IR06', 'Pasaje difícil C (2.28.6; 3.18.1; Dem. 30): la generación «inenarrable» y el Hijo «engendrado antes de toda la creación»', 'No sabemos cómo, pero afirma que el Hijo es engendrado y siempre está junto al Padre',
 [Q('I2-11','la',L('I2-11'),'Si alguno, pues, nos dijere: ¿cómo, entonces, el Hijo fue proferido por el Padre? le decimos que esa emisión (<i>prolatio</i>), o generación, o nominación, o apertura, o con el nombre que alguien la quiera llamar, siendo su generación inenarrable, nadie la conoce: ni Valentín, ni Marción, ni Saturnino, ni Basílides, ni ángeles, ni arcángeles, ni principados, ni potestades, sino sólo el que engendró, el Padre, y el que nació, el Hijo.','Contra las herejías 2.28.6 (Harvey, p. 355; en inglés, ANF p. 401, captura IR21)',H),
  Q('I4-07','la',L('I4-07', None, 'exsistens semper apud Patrem;'),'Demostrado claramente que el Verbo que estaba en el principio junto a Dios, por quien todo fue hecho, que estaba siempre presente al género humano, a éste, en los últimos tiempos, según el tiempo prefijado por el Padre, unido a su criatura, se hizo hombre pasible, queda excluida toda contradicción de los que dicen: «si entonces nació, antes no existía Cristo». Pues hemos mostrado que el Hijo de Dios no empezó entonces, existiendo siempre junto al Padre; […]','Contra las herejías 3.18.1 (ANF 3.18.1; Harvey, p. 95)',H),
  Q('I8-08','en',EN('I8-08'),'[…] de modo que según la carne fuese hijo de David, que fue hijo de Abrahán por larga sucesión; pero según el espíritu, Hijo de Dios, preexistente junto al Padre, engendrado antes de toda la creación del mundo, y al fin de los tiempos apareciendo a todo el mundo como hombre, el Verbo de Dios recapitulando en sí todo lo que hay en el cielo y en la tierra.','Demostración 30 (Robinson, p. 97)',ROB)],
 '<b>Por qué es difícil.</b> «Engendrado antes de toda la creación» (Dem. 30) es lenguaje de prioridad temporal que arrianos leen como «hubo un tiempo…»; «<i>prolatio</i>» es el término valentiniano. <b>Resolución.</b> (1) Ireneo usa <i>prolatio, generatio, nuncupatio, adapertio</i> como <b>sinónimos</b> y dice que <b>el modo</b> es inefable, no que no exista: «sólo el Padre que engendró y el Hijo que nació» lo conocen (2.28.6). (2) 3.18.1: el Hijo «<b>no empezó entonces</b>, existiendo <b>siempre junto al Padre</b>»: no es un comienzo en el tiempo. (3) Gregorio de Nacianzo (Or. 29.8): «¿cómo fue engendrado? Esta generación no sería gran cosa si pudieras comprenderla… no te atrevas a especular sobre ella»: la misma prudencia que Ireneo. <b>Límite.</b> «Engendrado antes de toda la creación» no es «desde la eternidad»; y la <i>Demostración</i> la leo solo en el inglés de Robinson. Los fragmentos «Pfaff» que dicen «engendrado antes de la luz» son dudosos y no los uso.')

add('IR07', 'Pasaje difícil D (3.6.1, 3.9.1): «sólo el Padre es Dios y Señor» frente a «el Espíritu designa a ambos con el nombre de Dios»', 'El Hijo llamado «Dios»',
 [Q('I3-06','la',L('I3-06', 'Similiter habet illud', 'qui ungit, id est Patrem.'),'Igualmente dice: «Tu trono, oh Dios, es eterno; vara de rectitud, vara de tu reino. Amaste la justicia y odiaste la iniquidad; por eso te ungió Dios, tu Dios». Pues el Espíritu designó a ambos con el nombre de Dios: tanto al Hijo que es ungido como al que unge, es decir, al Padre.','Contra las herejías 3.6.1 (Harvey, p. 21)',H),
  Q('I3-11','la',L('I3-11'),'Mostrado esto claramente aquí (y se mostrará aún más claramente), que ni los profetas, ni los apóstoles, ni el Señor Cristo en su propia persona confesaron a otro Señor o Dios, sino principalmente a Dios y Señor: confesando los profetas y los apóstoles al Padre y al Hijo, sin nombrar Dios a ningún otro ni confesar Señor a ningún otro; y el mismo Señor enseñando a sus discípulos que sólo el Padre es Dios y Señor, que es el único Dios y dominador de todo […]','Contra las herejías 3.9.1 (Harvey, p. 30)',H),
  Q('I8-10','en',EN('I8-10'),'Así, pues, el Padre es Señor y el Hijo es Señor, y el Padre es Dios y el Hijo es Dios; porque lo que es engendrado de Dios es Dios. Y así, en la sustancia y poder de su ser se muestra un solo Dios; pero hay también, según la economía de nuestra redención, Hijo y Padre.','Demostración 47 (Robinson, p. 112)',ROB+'; «sustancia» es la elección de Robinson para un término armenio dudoso')],
 '<b>Por qué es difícil.</b> 3.9.1: «<i>Patrem tantum Deum et Dominum… qui solus est Deus</i>» es el texto que citan arrianos y unitarios. <b>Resolución.</b> (1) El contraste es con «<b>otro</b> Dios» (el demiurgo gnóstico), no con el Hijo: la misma frase dice que «los profetas y los apóstoles confesaban al <b>Padre y al Hijo</b>». (2) En 3.6.1 el Espíritu «designa a ambos con el nombre de Dios» (<i>utrosque Dei appellatione</i>): el Hijo ungido y el Padre que unge. (3) Dem. 47: «el Hijo es Dios, porque lo engendrado de Dios es Dios», con un solo Dios «en sustancia y poder» y distinción «según la economía». <b>Límite.</b> El argumento es de nombres bíblicos, no un análisis del ser; «sustancia» es la traducción de Robinson de un término armenio incierto, y la tradición posterior (Nicea) precisa lo que Ireneo dice con «lo engendrado de Dios es Dios».')

add('IR08', 'Pasaje difícil E (4.4.2, 4.6.3-6): «el Hijo es la medida del Padre» y «el Padre es lo invisible del Hijo»', 'Visible e invisible: ¿conocimiento desigual?',
 [Q('I5-03','la',L('I5-03'),'Pues Dios hace todas las cosas con medida y orden, y nada hay sin medida en él, porque nada es incompuesto. Y bien dijo quien dijo que el Padre inmenso fue medido en el Hijo: pues el Hijo es la medida del Padre, porque también lo contiene.','Contra las herejías 4.4.2 (Harvey, p. 153)',H),
  Q('I5-06','la',L('I5-06'),'Pues nadie puede conocer al Padre sino por el Verbo de Dios, es decir, si el Hijo se lo revela; ni al Hijo sino por el beneplácito del Padre. Y el Hijo cumple el beneplácito del Padre: pues el Padre envía, y el Hijo es enviado y viene. Y al Padre invisible e indeterminable, en cuanto es a nosotros, lo conoce su propio Verbo, y siendo inenarrable, él mismo lo narra para nosotros; a su vez, al Verbo suyo sólo lo conoce el Padre.','Contra las herejías 4.6.3 (Harvey, p. 159)',H),
  Q('I5-09','la',L('I5-09'),'Y por medio del mismo Verbo hecho visible y palpable, el Padre se mostraba, aunque no todos le creían igualmente; pero todos veían en el Hijo al Padre: pues lo invisible del Hijo es el Padre, y lo visible del Padre es el Hijo. Y por eso todos, estando él presente, decían «Cristo» y lo llamaban Dios.','Contra las herejías 4.6.6 (Harvey, p. 161)',H)],
 '<b>Por qué es difícil.</b> «Medida» (el Hijo «mide» al Padre inmenso), «enviado» y «el Padre invisible» suenan a jerarquía de conocimiento. <b>Resolución.</b> (1) La frase de 4.6.3 es sobre <b>revelación «a nosotros»</b> (<i>quantum ad nos est</i>): el Padre es invisible e indeterminable «en cuanto a nosotros»; el Verbo lo hace visible. (2) «Medida» se explica en la misma frase: «porque también lo <b>contiene</b>» (<i>capit eum</i>): el Hijo es el lugar de la revelación, no un límite impuesto desde fuera; la «medida» de 4.4.2 se atribuye a quien «bien dijo» (cita). (3) Atanasio (Or. 1.20): «¿cuándo estuvo Dios sin lo que le es propio?»: lo que es propio de la esencia del Padre (el Hijo) no es extraño a ella. Aquino (ST I q.42 a.5): el Padre está en el Hijo por la esencia. <b>Límite.</b> 4.4.2 es una cita que Ireneo hace; en 4.19.2 «medida» es otra cosa (el Padre mide con su palma: Is 40:12): no confundirlas. «Enviado» (4.6.3) es la misión del Hijo, no su inferioridad de naturaleza; es lenguaje de subordinación de origen.')

add('IR09', 'Las «manos» de Dios: el Hijo y el Espíritu', 'Lo que dicen 4.20.1, 5.6.1, 5.28.4 y la Demostración 11', 
 [Q('I6-01','la',L('I6-01'),'No nos hicieron, pues, los ángeles, ni nos plasmaron, ni los ángeles pudieron hacer la imagen de Dios, ni otro alguno fuera del Verbo del Señor, ni una potencia lejos del Padre de todos. Pues Dios no necesitaba de éstos para hacer lo que él mismo había determinado hacer, como si él mismo no tuviera sus manos. Pues siempre están junto a él el Verbo y la Sabiduría, el Hijo y el Espíritu, por quienes y en quienes todo lo hizo libre y espontáneamente.','Contra las herejías 4.20.1 (Harvey, p. 213; captura IR20)',HV),
  Q('I7-03','la',TX('I7-03', None, 'sed non pars hominis.'),'Pues por las manos del Padre, es decir, por el Hijo y el Espíritu, se hace el hombre a semejanza de Dios, y no sólo una parte del hombre.','Contra las herejías 5.6.1 (Harvey, p. 333)','Latín: Harvey 1857; OCR, sin cotejar con imagen'),
  Q('I7-11','la',TX('I7-11', None, 'Dei, id est, Filii et Spiritus,') if False else L('I7-11'),'Y por eso, en todo tiempo, el hombre plasmado desde el principio por las manos de Dios, es decir, del Hijo y del Espíritu, se hace según la imagen y semejanza de Dios; arrojada la paja, que es la apostasía, y recogido el trigo en el granero, que son los que fructifican para Dios por la fe.','Contra las herejías 5.28.4 (Harvey, p. 403)','Latín: Harvey 1857; OCR, sin cotejar con imagen')],
 '<b>Corrección importante.</b> En 4.20.1 el texto dice «<i>quasi ipse suas non haberet manus</i>. <b>Adest enim ei semper Verbum et Sapientia, Filius et Spiritus</b>»: la frase «Verbo… Hijo y Espíritu» sigue a la mención de las manos; la identificación explícita «las manos de Dios = el Hijo y el Espíritu» está en el <b>libro 5</b> (5.6.1, 5.28.4), no en 4.20.1; en 4.7.4 la ANF habla de «servir», no de manos. En la <i>Demostración</i> 11 solo dice «con sus propias manos»; que sean Hijo y Espíritu lo anota Robinson. <b>Qué significa.</b> «Por las manos de Dios» = «por sí mismo»: Ireneo niega a los ángeles el papel de plasmadores. Bull (<i>Defensio</i>, p. 172): hace el mundo «por su propia descendencia… por sus propias manos, es decir, por el Hijo y el Espíritu Santo». <b>Objeción.</b> «Manos» = instrumentos del Padre; Bull responde que no son ministros extraños sino «de una misma naturaleza» (su lectura). <b>Límite.</b> El Padre no aparece en 5.6.1 ni 5.28.4; «manos» es metáfora.')

add('IR10', 'Pasaje difícil F (4.20.3): «el Verbo, es decir, el Hijo… la Sabiduría, que es el Espíritu», y Prov 8:22 «el Señor me creó»', 'Ireneo identifica la Sabiduría con el Espíritu; Justino y Teófilo, con el Hijo',
 [Q('I6-03','la',L('I6-03'),'Y que el Verbo, es decir, el Hijo, estaba siempre con el Padre, lo hemos demostrado con muchos argumentos. Y que también la Sabiduría, que es el Espíritu, estaba junto a él antes de toda constitución, dice por Salomón: «Dios con sabiduría fundó la tierra, y con prudencia preparó el cielo. Con su sentido brotaron los abismos, y las nubes destilaron rocío».','Contra las herejías 4.20.3 (Harvey, p. 214; captura IR20 y IR21)',H+'; p. 214 vista en imagen'),
  Q('I6-04','la',L('I6-04', 'Et rursus autem', 'genuit me.'),'Y de nuevo: «El Señor me creó como principio de sus caminos para sus obras; antes de los siglos me fundó, en el principio, antes de hacer la tierra, antes de constituir los abismos, y antes de que salieran las fuentes de las aguas, antes de que los montes se afirmaran: antes de todos los collados me engendró».','Contra las herejías 4.20.3 (Harvey, pp. 214-215)',H),
  Q('I11-13','en',TX('I11-13') if False else EN('I11-13'),'[…] ya que él sirve a la voluntad del Padre, y ya que fue engendrado del Padre por un acto de voluntad […] El Verbo de la Sabiduría, que es él mismo este Dios engendrado del Padre de todas las cosas, y Verbo, y Sabiduría, y Poder, y Gloria del que lo engendró.','Justino, Diálogo 61 (ANF vol. 1, p. 227)','Inglés: Dods y Reith, ANF vol. 1')],
 '<b>Por qué es difícil.</b> (a) Ireneo aplica Prov 8:22-31 («creó… engendró») a la Sabiduría y dice que la Sabiduría <b>es el Espíritu</b>; Justino (Dial. 61) y Teófilo (Autol. 2.10) la leen del Hijo. (b) «Creó» (<i>creavit</i>) en Prov 8:22 suena a criatura. <b>Resolución.</b> (1) La frase del propio Ireneo distingue: «el Verbo, <b>es decir el Hijo</b>… y la Sabiduría, <b>que es el Espíritu</b>»: <b>dos</b>, ambos «siempre» con el Padre, «antes de toda constitución». (2) El texto latino lee «<i>creavit me</i>… <i>genuit me</i>»: el final es «engendró»; la ANF lo vierte «brought me forth». (3) Atanasio (<i>C. Ar.</i> II.60) distingue «creó» y «engendró» en Prov 8 (según los investigadores); y Atanasio rechaza que la Sabiduría creadora sea una criatura. <b>Honestidad.</b> No hay unanimidad patrística sobre Prov 8: Ireneo (Sabiduría = Espíritu) y Justino-Teófilo (Sabiduría = Hijo) <b>difieren</b>; eso es una limitación del siglo II, no una negación. Ireneo es el primero en separar nítidamente Verbo-Hijo y Sabiduría-Espíritu como dos «manos».')

add('IR11', 'Pasaje difícil G (4.20.2, 4.38.3, 5.18.2, 5.20.2, 5.36.2): «Padre sobre todos», «cabeza del Espíritu», «el Hijo sujeto»', 'Orden y subordinación en Ireneo',
 [Q('I6-02','la',L('I6-02'),'Bien también dice Malaquías entre los profetas: «¿No es un solo Dios el que nos ha constituido? ¿No es uno solo el Padre de todos nosotros?». Y consecuentemente el Apóstol dice: «Un solo Dios Padre, que está sobre todos y en todos nosotros». Igualmente el Señor: «Todo me ha sido entregado por mi Padre»; manifiestamente por el que hizo todo: pues no le entregó cosas ajenas, sino suyas.','Contra las herejías 4.20.2 (Harvey, p. 214)',H),
  Q('I7-07','la',L('I7-07'),'Sobre todo está el Padre, y él mismo es cabeza de Cristo; por todo, el Verbo, y él mismo es cabeza de la Iglesia; y en todos nosotros, el Espíritu, y él mismo es agua viva […] Pues el Padre, llevando a la vez la creación y su Verbo, y el Verbo llevado por el Padre, da el Espíritu a todos, como quiere el Padre.','Contra las herejías 5.18.2 (Harvey, pp. 373-374)','Latín: Harvey 1857; OCR, sin cotejar con imagen'),
  Q('I7-10','la',L('I7-10'),'[…] uniendo al hombre con el Espíritu y colocando el Espíritu en el hombre, él mismo se hizo cabeza del Espíritu, y da al Espíritu ser cabeza del hombre: pues por él vemos, oímos y hablamos.','Contra las herejías 5.20.2 (Harvey, p. 380)','Latín: Harvey 1857; OCR, sin cotejar con imagen'),
  Q('I7-12','la',L('I7-12'),'[…] y por el Espíritu ascienden al Hijo, y por el Hijo ascienden al Padre; cediendo después el Hijo al Padre su obra, como dice también el Apóstol: «Es necesario que él reine hasta poner a todos sus enemigos bajo sus pies» […] entonces el mismo Hijo se sujetará al que le sujetó todo, para que Dios sea todo en todos.','Contra las herejías 5.36.2 (Harvey, p. 428)','Latín: Harvey 1857 (la página la vio un investigador); atribuido por Ireneo a los presbíteros')],
 '<b>Por qué es difícil.</b> «Padre sobre todos», «cabeza de Cristo», «el Hijo… cabeza del Espíritu», «el Hijo se sujetará…» y «el Hijo sirve» (4.38.3: «el Padre planeando y mandando, el Hijo ministrando y formando, el Espíritu nutriendo y haciendo crecer») se leen como una escala. Además, 4.38.3: «solo Dios es increado» (<i>solus infectus</i>). <b>Resolución.</b> (1) 4.20.2 es una cita de Ef 4:6 contra el demiurgo: «sobre todos» no se opone al Hijo, a quien el Padre «entregó cosas suyas, no ajenas». (2) 5.18.2 es un <b>orden de acción</b>: el Padre «sobre todo», el Verbo «por todo», el Espíritu «en todos»: tres modos de presencia del mismo Dios (la fórmula la retoma Basilio: orden sin desigualdad). (3) 5.20.2 («cabeza del Espíritu») es recapitulación: el Hijo hecho hombre une al hombre con el Espíritu; (4) 5.36.2 es atribuido por Ireneo a los <b>presbíteros</b> y cita 1 Cor 15:28; la tradición lo lee de la humanidad de Cristo («el Cuerpo se sujeta»). <b>Límite.</b> Son textos de subordinación de origen y economía; Bethune-Baker llama a esta relación «un misterio» y reconoce una «cierta subordinación» (IR15). «Solo Dios increado» (4.38.3) se lee en contexto: Dios solo es sin principio y causa de todo, y el resto «está sujeto a Dios».')

add('IR12', 'El Espíritu Santo en Ireneo: 3.17, 3.24.1, 4.20.5-6, 4.33.15 y la Demostración 6-10', 'Persona que obra, o «poder» y «Sabiduría» del Padre',
 [Q('I4-06','la',L('I4-06'),'Pues éste prometió por los profetas derramar en los últimos tiempos sobre siervos y siervas, para que profeticen: de ahí que también descendió sobre el Hijo de Dios, hecho Hijo del Hombre, acostumbrándose con él a habitar en el género humano y a reposar en los hombres y a habitar en la criatura de Dios, obrando en ellos la voluntad del Padre y renovándolos de la vejez a la novedad de Cristo.','Contra las herejías 3.17.2 (ANF 3.17.2; Harvey, p. 92)',H),
  Q('I4-12','la',L('I4-12'),'[…] Pues donde está la Iglesia, allí está también el Espíritu de Dios; y donde está el Espíritu de Dios, allí está la Iglesia y toda gracia: y el Espíritu es la verdad. Por lo cual los que no participan de él ni se alimentan de los pechos de la madre para la vida, ni perciben la fuente nitidísima que procede del cuerpo de Cristo […]','Contra las herejías 3.24.1 (Harvey, p. 132)',H),
  Q('I6-14','la',L('I6-14'),'[…] el espiritual […] conociendo siempre al mismo Dios, y siempre conociendo al mismo Verbo de Dios, aunque ahora se nos ha manifestado; y siempre conociendo al mismo Espíritu de Dios, aunque en los últimos tiempos se ha derramado de modo nuevo sobre nosotros, y desde la creación del mundo hasta el fin sobre el mismo género humano.','Contra las herejías 4.33.15 (Harvey, p. 269)',H),
  Q('I8-06','en',EN('I8-06'),'Ahora bien, este Dios es glorificado por su Verbo, que es su Hijo, continuamente, y por el Espíritu Santo, que es la Sabiduría del Padre de todo: y los poderes de éstos, es decir, del Verbo y de la Sabiduría, que se llaman Querubines y Serafines, glorifican con voces incesantes a Dios; y toda cosa creada que está en los cielos ofrece gloria a Dios Padre de todo.','Demostración 10 (Robinson, p. 79)',ROB)],
 '<b>Qué dice.</b> El Espíritu «descendió» sobre el Hijo hecho hombre, «obra en ellos la voluntad del Padre», «expone las disposiciones del Padre y del Hijo» (4.33.7), es «verdad», «Sabiduría del Padre» (Dem. 10) y «el mismo Espíritu de Dios» siempre (4.33.15). 4.20.5-6: «el Espíritu obrando, el Hijo administrando, el Padre aprobando». <b>Objeción.</b> Son pasajes de <b>función</b>, no dicen «persona» ni «Dios» del Espíritu; Bethune-Baker y Newman no hallan una doctrina elaborada del Espíritu en estas secciones. <b>Respuesta.</b> Ireneo enumera siempre al Espíritu <b>distinto</b> del Padre y del Hijo («el mismo Dios… el mismo Verbo… el mismo Espíritu»), le atribuye voluntad de obrar «la voluntad del Padre» y lo coloca en las «manos» de Dios (IR09); Basilio y Gregorio completarán lo que Ireneo no define. <b>Límite.</b> Hay un mínimo: Ireneo dice que el Espíritu es «Sabiduría» (Dem. 10, 4.20.3), un término de relación, y nunca dice «Dios» del Espíritu en términos explícitos que yo haya visto.')

add('IR13', 'Lo que Ireneo NO dice y correcciones al material de partida', 'Resultados de las comprobaciones de los once investigadores',
 [],
 '<b>Correcciones verificadas.</b> (1) «Por el Verbo y el Espíritu» es 1.22.1; 2.2.4-5 dice solo «Verbo»; 2.30.9, «Verbo y Sabiduría» (no «Verbo y Espíritu… siempre con él»). (2) La identificación literal «manos = Hijo y Espíritu» está en el <b>libro 5</b> (5.6.1, 5.28.4) y en el prefacio del libro 4; no en 4.20.1 ni 4.7.4. (3) «El Padre es lo invisible del Hijo» es 4.6.6; «medida» es 4.4.2 (no 4.11.4). (4) «Padre de todos» está en 3.6.5, no 3.8.3. (5) «Padre sobre todos» está en 4.20.2, no 4.20.5-6. (6) «Padre mayor» y «Mc 13:32» están en 2.28.8 y 2.28.6. (7) «Tres artículos» no está en la <i>Demostración</i>: dice «tres puntos». (8) La numeración de Harvey va una unidad por encima de la ANF en 3.16-3.25 (p. ej. ANF 3.16.6 = Harvey 3.17.6). <b>Sin hallar / no usado.</b> «Homoousios» no es término de Ireneo (Newman, p. 189: los valentinianos usaban «consustancial» en sentido filosófico); los «Fragmentos de Pfaff» son espurios o dudosos; ningún texto de Atanasio leído (NPNF2) <b>nombra a Ireneo</b>; solo las notas del editor lo hacen. <b>Límite.</b> El griego casi no se conserva: citamos el latín de un traductor; la <i>Demostración</i> solo en inglés.')

add('IR14', 'Lo que dicen los estudiosos (1): a favor de la intención trinitaria', 'Bull y Bethune-Baker', 
 [Q('I10-01','en',TX('I10-01'),'Contra ellos, el santo obispo, en todas partes de sus escritos, afirma y prueba estos dos puntos: primero, que este mundo no fue creado de ningún modo por poderes inferiores, ajenos a la esencia y naturaleza del Dios Altísimo, sino que fue hecho por el mismo Dios Altísimo, por medio de «su propia descendencia» y de «sus propias manos» (por usar las palabras mismas de Ireneo), es decir, por el Hijo y el Espíritu Santo.','Bull, Defensio fidei Nicaenae (Oxford 1851), p. 172','Inglés: Bull (trad. 1851)'),
  Q('I10-03','en',TX('I10-03'),'En estos pasajes Ireneo afirma tal identidad de esencia (salvando siempre la distinción de personas) entre el Padre, el Hijo y el Espíritu Santo (a quien, con Teófilo de Antioquía y otros, designa con el nombre de Sabiduría), que dice que el Padre, al crear el mundo por el Hijo y el Espíritu Santo, lo hizo por sí mismo.','Bull, Defensio, p. 174','Inglés: Bull (trad. 1851)'),
  Q('I10-11','en',TX('I10-11'),'Pero la distinción personal se mantiene estrictamente: e insiste en que es una y la misma persona —Jesucristo— el Logos, el Hijo de Dios, quien creó el mundo, nació como hombre, y sufrió y ascendió al cielo, todavía hombre además de Dios.','Bethune-Baker, Introduction to the Early History of Christian Doctrine (1903), p. 131','Inglés: Bethune-Baker (Methuen)')],
 '<b>Qué muestra.</b> Bull (1685) lee en «hijo y Espíritu… sus propias manos» una <b>identidad de esencia con distinción de personas</b>; Bethune-Baker ve en Ireneo una cristología de una sola persona, el Logos-Hijo, con «distinción personal estrictamente mantenida». <b>Cautelas.</b> (1) Bull es un abogado nicenista del siglo XVII: «identidad de esencia» y «distinción de personas» son <b>glosas suyas</b>, no el vocabulario de Ireneo (que, en el latín, no usa «esencia» ni «persona» así). (2) Bethune-Baker habla de la cristología, no del Espíritu: no halla en esa sección discusión del Espíritu.')

add('IR15', 'Lo que dicen los estudiosos (2): las objeciones', 'Newman, Bethune-Baker y el problema de la traducción latina',
 [Q('I10-07','en',TX('I10-07'),'Por tanto, los escritores primitivos, con una explicitud sin sospecha y reverente, dan por supuesto el carácter «ministerial» de la relación tanto del Hijo como del Espíritu hacia el Padre; hablando, desde luego, de ellos como incluidos en la Unidad divina, no como externos a ella. Así Ireneo, claro e innegable como es su ortodoxia, declara con todo que el Padre «es servido en todas las cosas por su propia Descendencia y Semejanza, el Hijo y el Espíritu Santo, el Verbo y la Sabiduría, de quienes todos los ángeles son siervos y sujetos».','Newman, The Arians of the Fourth Century, p. 166 (cita Haer. 4.7.4)','Inglés: Newman (Longmans)'),
  Q('I10-10','en',TX('I10-10'),'Concibe al Logos como el único gran y absoluto órgano de todas las revelaciones divinas de todos los tiempos (de modo que en ellas no fue Dios mismo sino el Logos quien apareció), y aparentemente con alguna clase de subordinación del Logos, pero su sentimiento religioso y la conciencia de las limitaciones del entendimiento humano le impiden llevar lejos sus investigaciones sobre la naturaleza de las relaciones entre el Padre y el Hijo. Son un misterio. El Padre es Dios que se revela; el Hijo es Dios revelado. El Padre es lo invisible del Hijo, mientras que el Hijo es lo visible del Padre.','Bethune-Baker, Introduction, pp. 130-131','Inglés: Bethune-Baker (Methuen)'),
  Q('I10-05','en',TX('I10-05'),'[…] ¡pensamiento y sentido!: por cuyas palabras es cierto que el traductor de Ireneo solía expresar <i>énnoia</i> o <i>sigḗ</i> (pensamiento o silencio) y <i>noûs</i> (mente).','Bull, Defensio, vol. 2, p. 391','Inglés: Bull (trad. 1851); texto cortado')],
 '<b>Lectura honesta.</b> Newman (p. 166) reconoce el carácter «ministerial» del Hijo y del Espíritu en Ireneo (incluidos en la Unidad divina); Bethune-Baker ve «alguna clase de subordinación», la considera un misterio y preniceña, y nota que Ireneo no profundiza. Bull (vol. 2) avisa de que el traductor latino vertía <i>énnoia, sigḗ</i> y <i>noûs</i> con un criterio propio, lo que condiciona las inferencias lingüísticas (aquí no se sabe qué decía el griego en muchos casos). <b>Mi posición.</b> Ireneo es el testigo más fuerte del siglo II (Padre, Hijo y Espíritu siempre con él; el Hijo «Dios»; generación inefable), pero su lenguaje es económico y de subordinación de origen; no defiendo que formulara Nicea. <b>Pendiente:</b> Kelly, Lawson, Briggman, Behr, Osborn y Steenberg no se pudieron abrir (restringidos).')

add('IR16', 'Cómo lo resuelve la teología posterior (1): Mc 13:32 y la generación inefable', 'Agustín, Aquino, Atanasio y Gregorio de Nacianzo',
 [Q('I11-11','en',EN('I11-11'),'Y también: «De aquel día y de aquella hora nadie sabe, ni los ángeles que están en el cielo, ni el Hijo, sino el Padre». Pues él lo ignora como haciendo ignorarlo a otros; es decir, en cuanto no lo supo de tal modo que lo mostrara entonces a sus discípulos.','Agustín, De Trinitate I.12','Inglés: Haddan, NPNF 1.ª serie vol. 3'),
  Q('I11-10','en',EN('I11-10'),'Se dice, por tanto, que no sabe el día y la hora del Juicio porque no lo da a conocer […] Pero se dice que el Padre lo sabe porque comunicó este conocimiento al Hijo. De ahí que, al decir «sino el Padre», se nos da a entender que el Hijo lo sabe, no sólo en la naturaleza divina, sino también en la humana.','Aquino, ST III q.10 a.2 ad 1','Inglés: Dominicos ingleses (newadvent)'),
  Q('I11-08','en',EN('I11-08'),'[…] sepamos, los que amamos a Cristo y llevamos a Cristo dentro, que el Verbo, no como ignorante, considerado como Verbo, ha dicho «no lo sé», pues sabe, sino mostrando su humanidad, pues ignorar es propio del hombre […]','Atanasio, Contra los arrianos 3.45','Inglés: Newman y Robertson, NPNF 2.ª serie vol. 4'),
  Q('I11-12','en',EN('I11-12'),'¿Cómo fue engendrado, entonces? Esta Generación no sería gran cosa si pudieras comprenderla […] Y no te atrevas, aun entonces, a especular sobre la Generación de Dios; pues sería inseguro. Pues aunque supieras todo sobre la tuya, de ningún modo sabes sobre la de Dios.','Gregorio de Nacianzo, Or. 29.8 (Tercera Oración Teológica)','Inglés: Browne y Swallow, NPNF 2.ª serie vol. 7')],
 '<b>Aplicación a Ireneo (mía).</b> Las tres explicaciones de Mc 13:32 (no lo «revela»; lo ignora «como hombre»; el Padre lo sabe porque se lo comunicó) se parecen a la salida de Ireneo («reservar a Dios lo que es mayor que nosotros»), que solo da una regla de humildad. La <b>generación inefable</b> la defiende Gregorio con el mismo argumento («no te atrevas a especular»). <b>Honestidad.</b> Ninguna de estas fuentes cita a Ireneo; Aquino y Agustín dan una explicación metafísica que Ireneo no formula; los textos son en inglés (newadvent, NPNF).')

add('IR17', 'Cómo lo resuelve la teología posterior (2): inhabitación, «medida» y «manos»', 'Aquino, Atanasio y Tertuliano',
 [Q('I11-09','en',EN('I11-09'),'El Padre está en el Hijo por su esencia, pues el Padre es su propia esencia, y comunica su esencia al Hijo sin cambio alguno de su parte […] puesto que el Hijo es su propia esencia, se sigue que él mismo está en el Padre, en quien está su esencia.','Aquino, ST I q.42 a.5','Inglés: Dominicos ingleses (newadvent)'),
  Q('I11-07','en',EN('I11-07'),'¿Cuándo, pues, estuvo Dios sin lo que le es propio? ¿O cómo puede uno considerar lo que es propio como extraño y ajeno en esencia?','Atanasio, Contra los arrianos 1.20','Inglés: Newman y Robertson, NPNF 2.ª serie vol. 4'),
  Q('I10-13','en',TX('I10-13'),'Son de un solo Dios, que usa su propio Verbo como una Mano, y en él lo hace todo. Esto mismo nos lo muestra Dios cuando dice: «Todas estas cosas las ha hecho mi Mano».','Atanasio, Contra los arrianos (NPNF 2.ª serie vol. 4)','Inglés: Robertson, NPNF 2.ª serie vol. 4 (nota de editor [787] aduce a Ireneo)'),
  Q('I11-16','en',EN('I11-16'),'¿Fue el Verbo de Dios proferido o no? […] Si fue proferido, reconoce entonces que la verdadera doctrina tiene una prolación; y no te preocupes por la herejía, cuando en algún punto imita la verdad.','Tertuliano, Adversus Praxean 8','Inglés: Holmes, ANF vol. 3')],
 '<b>Aplicación a Ireneo (mía).</b> «La medida del Padre» y «lo visible del Padre» (IR08) se leen con Aquino: <b>el Padre está en el Hijo por esencia</b> y el Hijo en el Padre (ST I q.42 a.5); Atanasio (Or. 1.20): lo que es propio de Dios no es ajeno a su esencia; y Atanasio usa la imagen de la «Mano» para el Verbo («usa su propio Verbo como una Mano»): es la herencia de la metáfora de Ireneo (nota del editor). Tertuliano admite «prolación» donde Ireneo la rechaza (con matices): ambos coinciden en que la «emisión» gnóstica es falsa. <b>Límite.</b> Atanasio, en los textos leídos, no nombra a Ireneo; la conexión es del editor. Aquino aclara que habla de 1.ª persona en la 2.ª por esencia, no que Ireneo lo dijera.')

add('IR18', 'Resumen de pasajes difíciles y cómo se resuelven', 'Veredicto honesto: el testigo más fuerte del siglo II; trinitario «en estructura», con lenguaje preniceno', [], '__TABLE__')
